const transcript = ($input.first().json.final_transcript || "").toLowerCase().trim();
const phone      = $input.first().json.patient_phone || "";
const callSid    = $input.first().json.call_sid || "";
const prevName       = $input.first().json.prev_name        || null;
const prevDate       = $input.first().json.prev_date        || null;
const prevReason     = $input.first().json.prev_reason      || null;
const prevBookingFor = $input.first().json.prev_booking_for || null;
const attempt    = $input.first().json.attempt     || "1";
const prevTimeSlot   = $input.first().json.prev_time_slot   || null;

const slots = {
  name: null,
  date: null,
  reason: null,
  raw_text: transcript,
  phone: phone,
  call_sid: callSid
};

// --- 1. RELATION & BOOKING FOR DETECTION (Run First to catch mid-sentence switches) ---
slots.booking_for = "Self";
const relations = {
  "मां": "Mother", "माँ": "Mother", "मम्मी": "Mother", "पापा": "Father", "पिता": "Father",
  "बेटी": "Daughter", "बेटे": "Son", "पत्नी": "Wife", "पति": "Husband", "भाई": "Brother", "बहन": "Sister",
  "papa": "Father", "pita": "Father", "maa": "Mother", "mummy": "Mother", "beti": "Daughter", "beta": "Son", "bhai": "Brother", "behen": "Sister"
};
for (const [hindi, english] of Object.entries(relations)) {
  if (transcript.includes(hindi)) { 
    slots.booking_for = english; 
    break; 
  }
}
slots.booking_for = (slots.booking_for !== "Self") ? slots.booking_for : (prevBookingFor || "Self");


// --- 2. ENHANCED NAME EXTRACTION WITH HONORIFIC STRIPPING ---
const namePatterns = [
  /mera\s+naam\s+([a-z0-9\u0900-\u097F]+(?:\s+[a-z0-9\u0900-\u097F]+)?)/i,
  /naam\s+([a-z0-9\u0900-\u097F]+(?:\s+[a-z0-9\u0900-\u097F]+)?)\s*(?:hai)?/i,
  /(?:unka|uska|inka|unki|uski)\s+naam\s+([^\s,।]+(?:\s+[^\s,।]+)?)/i,
  /(?:मेरा\s+नाम|नाम)\s+([^\s,।]+(?:\s+[^\s,।]+)?)\s*(?:है|हूँ)?/,
  /मैं\s+([^\s,।]+(?:\s+[^\s,।]+)?)\s*(?:हूँ|बोल\s+रह)/,
  /([^\s,।]+(?:\s+[^\s,।]+)?)\s+के\s+लिए\s+(?:अपॉइंटमेंट|appointment|दिखाना)/i,
  /([^\s,।]{2,})\s+बोल\s+रह[ाी]/
];

for (const pattern of namePatterns) {
  const match = transcript.match(pattern);
  if (match) { 
    slots.name = match[1].replace(/\s*(है|हूँ|hai|hoon)\s*$/i, "").trim(); 
    break; 
  }
}

// Fallback for standalone names (1-2 words raw turn response)
if (!slots.name && (prevName === null || prevName === "Unknown") && transcript.split(/\s+/).length <= 2 && transcript.length > 2) {
  slots.name = transcript.replace(/[.,। है हूं hai hoon]/g, "").trim();
}

// Strip out human titles/honorifics if caught in the regex match
if (slots.name) {
  slots.name = slots.name.replace(/^(dr|dr\.|doctor|mr|mr\.|mister|shri|shree|ji|डॉ|डॉक्टर|श्री|जी)\s+/i, "").trim();
  slots.name = slots.name.replace(/\s+(ji|जी)$/i, "").trim();
}

const notNames = ["कल", "आज", "परसों", "बुखार", "खांसी", "दर्द", "नहीं", "है", "हूँ", "आना", "जाना", "थोड़ा", "सांस", "kal", "aaj", "parso", "fever", "bukhar", "appointment", "subah", "shaam", "dopahar", "shyam", "morning", "evening", "appointment"];
if (slots.name && notNames.includes(slots.name.toLowerCase())) {
  slots.name = null;
}


// --- 3. INTELLIGENT DATE EXTRACTION (Handles rollover & word context) ---
const today = new Date();
const tomorrow = new Date(today); tomorrow.setDate(today.getDate() + 1);
const dayAfter = new Date(today); dayAfter.setDate(today.getDate() + 2);

const monthMap = {
  "जनवरी":0,"फरवरी":1,"मार्च":2,"अप्रैल":3,"मई":4,"जून":5,"जुलाई":6,"अगस्त":7,"सितंबर":8,"अक्टूबर":9,"नवंबर":10,"दिसंबर":11,
  "january":0,"february":1,"march":2,"april":3,"may":4,"june":5,"july":6,"august":7,"september":8,"october":9,"november":10,"december":11,
  "jan":0,"feb":1,"mar":2,"apr":3,"jun":5,"jul":6,"aug":7,"sept":8,"oct":9,"nov":10,"dec":11
};

if (transcript.includes("आज") || transcript.includes("aaj")) {
  slots.date = today.toLocaleDateString("en-IN");
} else if (transcript.includes("कल") || transcript.includes("kal")) {
  slots.date = tomorrow.toLocaleDateString("en-IN");
} else if (transcript.includes("परसों") || transcript.includes("parso")) {
  slots.date = dayAfter.toLocaleDateString("en-IN");
} else {
  let dateMatched = false;
  for (const [monthName, monthNum] of Object.entries(monthMap)) {
    const monthPattern = new RegExp(`(\\d{1,2})(?:st|nd|rd|th)?\\s*${monthName}`, 'i');
    const match = transcript.match(monthPattern);
    if (match) {
      const d = new Date(today.getFullYear(), monthNum, parseInt(match[1]));
      slots.date = d.toLocaleDateString("en-IN");
      dateMatched = true;
      break;
    }
  }

  if (!dateMatched) {
    const numMatch = transcript.match(/(?:tarikh|तारीख|date|ko|को)\s*(\d{1,2})|(\d{1,2})\s*(?:tarikh|तारीख|date|ko|को)/i);
    if (numMatch) {
      const targetDay = parseInt(numMatch[1] || numMatch[2]);
      if (targetDay >= 1 && targetDay <= 31) {
        let targetMonth = today.getMonth();
        // Edge Case: If day has already passed or they say "next month" ("agle mahine")
        if (targetDay < today.getDate() || transcript.includes("agle mahine") || transcript.includes("अगले महीने")) {
          targetMonth += 1;
        }
        const d = new Date(today.getFullYear(), targetMonth, targetDay);
        slots.date = d.toLocaleDateString("en-IN");
      }
    }
  }
}


// --- 4. EXPANDED MEDICAL REASON & DISTRESS PHRASES ---
const medicalKeywords = [
  "bukhaar", "bukhar", "khansi", "sardee", "sardi", "dard", "pet", "sir", "headache", "stomach",
  "बुखार","खांसी","सर्दी","दर्द","चोट","जाँच","checkup","चेकअप",
  "उल्टी","दस्त","सिरदर्द","पेट दर्द","कमर दर्द","आँख","teeth",
  "कान","गला","दांत","एलर्जी","डायबिटीज","शुगर","सांस","थकान","बीपी","bp","fever","dikhana","दिखाना","pain","दवाई","cough",
  "vomiting", "weakness", "allergy", "infection", "consultation", "consult"
];

const vagueDistressPhrases = [
  "tabiyat kharab", "tabiyat khraab", "tabiat kharab", "तबीयत खराब",
  "bimar hu", "bimar hoon", "बीमार", "swasthya", "theek nahi", "thik nahi"
];

for (const kw of medicalKeywords) {
  if (transcript.includes(kw.toLowerCase())) {
    slots.reason = kw;
    break;
  }
}

if (!slots.reason) {
  const isVague = vagueDistressPhrases.some(phrase => transcript.includes(phrase));
  if (isVague) {
    slots.reason = "General Checkup";
  } else {
    const reasonMatch = transcript.match(/(?:के\s+लिए|की\s+समस्या|तकलीफ|liye|problem|vajah\s+se)\s*(.{0,30})/i);
    if (reasonMatch) slots.reason = reasonMatch[0].trim();
  }
}


// --- 5. TIME SLOT EXTRACTION (Phonetic Resilience) ---
const timePatterns = [
  { re: /(?:subah|सुबह|morning)\s*(\d{1,2})/i,                       period: "Morning",   offset: 0  },
  { re: /(?:dopahar|दोपहर|afternoon|dophr|dopar|dopahra)\s*(\d{1,2})/i,period: "Afternoon", offset: 12 },
  { re: /(?:shaam|शाम|sham|shyam|evening|shaah)\s*(\d{1,2})/i,        period: "Evening",   offset: 12 },
  { re: /(?:raat|रात|night)\s*(\d{1,2})/i,                            period: "Night",     offset: 12 }
];

const periodOnly = [
  { words: ["subah","सुबह","morning","morn"],                       slot: "Morning",   display: "Morning (9:00-12:00)"   },
  { words: ["dopahar","दोपहर","afternoon","dophr","dopar","noon"], slot: "Afternoon", display: "Afternoon (12:00-16:00)" },
  { words: ["shaam","शाम","sham","shyam","evening","shaah"],        slot: "Evening",   display: "Evening (16:00-19:00)"  },
  { words: ["raat","रात","night"],                                  slot: "Night",     display: "Night (19:00-21:00)"     },
];

slots.time_slot = null;
slots.time_slot_display = null;

for (const p of timePatterns) {
  const m = transcript.match(p.re);
  if (m) {
    let hour = parseInt(m[1]);
    if (hour >= 1 && hour <= 12) {
      const h24 = (p.offset === 12 && hour < 12) ? hour + 12 : hour;
      slots.time_slot         = `${p.period} ${String(h24).padStart(2, "0")}:00`;
      slots.time_slot_display = `${p.period} ${String(h24).padStart(2, "0")}:00`;
      break;
    }
  }
}

if (!slots.time_slot) {
  for (const p of periodOnly) {
    if (p.words.some(w => transcript.includes(w.toLowerCase()))) {
      slots.time_slot         = p.slot;
      slots.time_slot_display = p.display;
      break;
    }
  }
}


// --- 6. HISTORY RESILIENCE MERGING ---
const correctionKeywords = ["nahi", "nahin", "नहीं", "galat", "गलत", "actually", "change", "badlo", "बदलो", "wrong"];
const hasCorrection = correctionKeywords.some(k => transcript.includes(k));
const isTimeCorrection = ["subah","shaam","morning","evening","dopahar","dophr","shyam","raat"].some(w => transcript.includes(w));

slots.name = (slots.name && slots.name !== "") ? slots.name : (hasCorrection && !isTimeCorrection ? null : (prevName || null));
slots.date = (slots.date && slots.date !== "") ? slots.date : (hasCorrection && !isTimeCorrection ? null : (prevDate || null));
slots.reason = (slots.reason && slots.reason !== "") ? slots.reason : (hasCorrection && !isTimeCorrection ? null : (prevReason || null));

const extractedTimeSlot = slots.time_slot;
slots.time_slot = extractedTimeSlot ? extractedTimeSlot : (hasCorrection ? null : (prevTimeSlot && prevTimeSlot !== "" ? prevTimeSlot : null));
slots.time_slot_display = slots.time_slot_display || slots.time_slot || null;
slots.prev_time_slot    = slots.time_slot || "";


// --- 7. STRICT EMPTY SLOT CHECK ---
slots.missing = [];
if (!slots.name   || slots.name === "Unknown" || slots.name === "") slots.missing.push({ field: "name", hindi: "आपका नाम" });
if (!slots.date   || slots.date === "Not provided" || slots.date === "") slots.missing.push({ field: "date", hindi: "अपॉइंटमेंट की तारीख" });
if (!slots.time_slot || slots.time_slot === "Not provided" || slots.time_slot === "") slots.missing.push({ field: "time_slot", hindi: "कौन से समय पर आना है, सुबह या शाम" });
if (!slots.reason || slots.reason === "Not provided" || slots.reason === "") slots.missing.push({ field: "reason", hindi: "बीमारी का कारण" });

slots.all_collected = slots.missing.length === 0;
slots.attempt = attempt || "0";

return [{ json: slots }];

const input = $input.first().json;
const missing = input.missing || [];

if (input.is_wrong_number) {
  return [{ json: {
    twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="hi-IN">Koi baat nahi. Agar aapko appointment chahiye toh dobara call karein. Dhanyavaad!</Say><Hangup/></Response>`,
    gave_up: true,
    name: input.name || input.prev_name || "Unknown",
    date: input.date || input.prev_date || "Not provided",
    reason: input.reason || input.prev_reason || "Not provided",
    time_slot: input.time_slot || input.prev_time_slot || "Not provided",
    booking_for: input.booking_for || input.prev_booking_for || "Self",
    phone: input.phone || "",
    call_sid: input.call_sid || "",
    raw_text: input.raw_text || "",
    status: "Incomplete"
  }}];
}

function buildQuestion(missingSlots) {
  if (missingSlots.length === 0) return null;
  const first = missingSlots[0].field;
  const questions = {
    name:      "क्षमा करें, मुझे आपका नाम सुनाई नहीं दिया। कृपया अपना पूरा नाम बताएं।",
    date:      "धन्यवाद! अब कृपया बताएं आप किस तारीख को अपॉइंटमेंट लेना चाहते हैं?",
    time_slot: "ठीक है! आप कौन सा समय चाहते हैं — सुबह, दोपहर, या शाम?",
    reason:    "कृपया बताएं आपको किस समस्या के लिए डॉक्टर से मिलना है?"
  };
  return questions[first] || `कृपया अपना ${missingSlots[0].hindi} बताएं।`;
}

const currentAttempt = parseInt(input.attempt || "0");

const partialData = {
  name:        input.name        || input.prev_name        || "Unknown",
  date:        input.date        || input.prev_date        || "Not provided",
  reason:      input.reason      || input.prev_reason      || "Not provided",
  time_slot:   input.time_slot   || input.prev_time_slot   || "Not provided",
  booking_for: input.booking_for || input.prev_booking_for || "Self",
  phone:       input.phone       || "",
  call_sid:    input.call_sid    || "",
  raw_text:    input.raw_text    || "",
  status:      "Incomplete"
};

if (currentAttempt >= 3) {
  return [{ json: {
    twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="hi-IN">Kshama karein, aap baad mein call karein. Dhanyavaad!</Say><Hangup/></Response>`,
    gave_up: true,
    ...partialData
  }}];
}

const question = buildQuestion(missing);

if (!question) {
  return [{ json: {
    twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="hi-IN">Dhanyavaad! Aapki jaankari prapt ho gayi.</Say><Hangup/></Response>`,
    gave_up: false,
    ...partialData
  }}];
}

const nextAttempt = currentAttempt + 1;

const prevName       = encodeURIComponent(partialData.name);
const prevDate       = encodeURIComponent(partialData.date);
const prevReason     = encodeURIComponent(partialData.reason);
const prevTimeSlot   = encodeURIComponent(partialData.time_slot);
const prevBookingFor = encodeURIComponent(partialData.booking_for);

const actionUrl = `https://grope-tanned-overcook.ngrok-free.dev/webhook/gather?prev_name=${prevName}&prev_date=${prevDate}&prev_reason=${prevReason}&prev_booking_for=${prevBookingFor}&prev_time_slot=${prevTimeSlot}&attempt=${nextAttempt}`;

const safeActionUrl = actionUrl.replace(/&/g, '&amp;');

const twiml = `<?xml version="1.0" encoding="UTF-8"?><Response><Gather input="speech" language="hi-IN" speechTimeout="auto" action="${safeActionUrl}" method="POST"><Say language="hi-IN">${question}</Say></Gather><Say language="hi-IN">क्षमा करें, कृपया दोबारा कॉल करें।</Say></Response>`;

return [{ json: {
  twiml,
  question_asked: question,
  attempt: nextAttempt,
  gave_up: false,
  ...partialData
}}];

const data = $('Code in JavaScript').first().json;

const name        = data.name        || "Unknown";
const date        = data.date        || "Not provided";
const reason      = data.reason      || "Not provided";
const phone       = data.phone       || "Not provided";
const booking_for = data.booking_for || "Self";
const time_slot  = data.time_slot_display || data.time_slot || "Not provided";
const booking_for_text = booking_for === "Self" ? "खुद के लिए" : `${booking_for} ke liye`;
const voice_confirmation = `${name} ji, aapki appointment ${date} ko ${time_slot} ke liye book ho gayi hai. ${booking_for === "Self" ? "" : booking_for + " ke liye."} Dhanyavaad!`;
const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
<Say voice="alice">Appointment booked successfully.</Say>
<Hangup/>
</Response>`;

const message = "New Appointment Booking\n\n" +
  "Patient Name: " + name + "\n" +
  "Phone Number: " + phone + "\n" +
  "Appointment Date: " + date + "\n" +
  "Time Slot: " + time_slot + "\n" +
  "Medical Reason: " + reason + "\n" +
  "Booking For: " + booking_for_text + "\n\n" +
  "Booked via AI Voice Bot\n" +
  "Time: " + new Date().toLocaleString('en-IN', {timeZone:'Asia/Kolkata'});

return [{ json: { ...data, whatsapp_message: message, voice_confirmation: voice_confirmation, twiml: twiml } }];
